test_snippets.cpp:
void check(Solution& solution) {
    assert(solution.isPalindrome("race a car") == vector<int>false);
    assert(solution.isPalindrome(" ") == vector<int>true);
    assert(solution.isPalindrome("Able was I ere I saw Elba") == vector<int>True);
    assert(solution.isPalindrome("__Level__) == vector<int>True);
    assert(solution.isPalindrome("No lemon) == vector<int>True);
    assert(solution.isPalindrome("0P") == vector<int>False);
    assert(solution.isPalindrome("_a!a_") == vector<int>True);
    assert(solution.isPalindrome("Never odd or even") == vector<int>True);
    assert(solution.isPalindrome("12345678987654321") == vector<int>True);
    assert(solution.isPalindrome("Was it a car or a cat I saw?") == vector<int>True);
    assert(solution.isPalindrome("No 'x' in Nixon") == vector<int>True);
    assert(solution.isPalindrome("Able was I) == vector<int>True);
    assert(solution.isPalindrome("12321") == vector<int>True);
    assert(solution.isPalindrome("Not a palindrome") == vector<int>False);
    assert(solution.isPalindrome("Able was I) == vector<int>True);
    assert(solution.isPalindrome("123abcba321") == vector<int>True);
    assert(solution.isPalindrome("Step on no pets") == vector<int>True);
    assert(solution.isPalindrome("A man) == vector<int>True);
    assert(solution.isPalindrome("Madam) == vector<int>True);
    assert(solution.isPalindrome("123abccba321") == vector<int>True);
    assert(solution.isPalindrome("__^_^__") == vector<int>True);
}

